// HasPrescription applies the HasEdge predicate on the "prescription" edge.
func HasPrescription() predicate.WalkInSale {
	return predicate.WalkInSale(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, PrescriptionTable, PrescriptionColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasPrescriptionWith applies the HasEdge predicate on the "prescription" edge with a given conditions (other predicates).
func HasPrescriptionWith(preds ...predicate.Prescription) predicate.WalkInSale {
	return predicate.WalkInSale(func(s *sql.Selector) {
		step := newPrescriptionStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.WalkInSale) predicate.WalkInSale {
	return predicate.WalkInSale(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.WalkInSale) predicate.WalkInSale {
	return predicate.WalkInSale(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.WalkInSale) predicate.WalkInSale {
	return predicate.WalkInSale(sql.NotPredicates(p))
}
